mc(12,1,'Thông hiểu','Carbohydrate','Glucose có thể tham gia phản ứng tráng bạc vì có thể tồn tại dạng mạch hở chứa nhóm',['ketone','aldehyde','ester','amide'],1,'Dạng mạch hở của glucose có nhóm –CHO nên có tính khử trong phản ứng tráng bạc.',{0:('K01','Nhầm dạng carbonyl của glucose và fructose.'),2:('K01','Nhầm nhóm chức ester.'),3:('K01','Nhầm nhóm amide.')})
mc(12,2,'Nhận biết','Amine','Công thức của methylamine là',['CH₃OH','CH₃COOH','CH₃NH₂','CH₃CHO'],2,'Methylamine là amine bậc một đơn giản có công thức CH₃NH₂.',{0:('K01','Nhầm alcohol với amine.'),1:('K01','Nhầm carboxylic acid với amine.'),3:('K01','Nhầm aldehyde với amine.')})
mc(12,2,'Thông hiểu','Amino acid','Chất vừa có nhóm amino vừa có nhóm carboxyl là',['glycine','ethanol','benzene','ethyl acetate'],0,'Glycine có cấu tạo NH₂–CH₂–COOH, chứa cả –NH₂ và –COOH.',{1:('K01','Alcohol không có đồng thời hai nhóm chức.'),2:('K01','Benzene không có nhóm amino/carboxyl.'),3:('K01','Ester không chứa đồng thời các nhóm đó.')})
mc(12,3,'Nhận biết','Polymer','Đơn vị mắt xích của polyethylene là',['–CH₂–CH(CH₃)–','–NH–CH₂–CO–','–CH=CH–','–CH₂–CH₂–'],3,'Trùng hợp CH₂=CH₂ tạo chuỗi (–CH₂–CH₂–)ₙ.',{0:('K01','Nhầm polyethylene với polypropylene.'),1:('K01','Nhầm polymer cộng với polyamide.'),2:('P01','Để nguyên liên kết đôi trong mắt xích polyethylene.')})
mc(12,4,'Thông hiểu','Điện hóa học','Ở pin điện hóa Zn–Cu hoạt động tự phát, electron đi qua dây dẫn ngoài từ',['Cu sang Zn','Zn sang Cu','dung dịch sang cực Cu','không có dòng electron'],1,'Zn bị oxi hóa ở anode, electron đi qua mạch ngoài từ Zn đến Cu.',{0:('L01','Đảo cực anode và cathode.'),2:('K02','Nhầm dịch chuyển ion với electron.'),3:('K01','Không nhận ra quá trình tự phát trong pin.')})
mc(12,5,'Thông hiểu','Kim loại','Sắt tiếp xúc trực tiếp với đồng trong không khí ẩm, kim loại dễ bị ăn mòn trước là',['sắt','đồng','cả hai luôn bằng nhau','không kim loại nào'],0,'Trong cặp Fe–Cu ở môi trường điện li, Fe hoạt động hơn, đóng vai trò anode và dễ bị oxi hóa.',{1:('L01','Nhầm chiều ưu tiên bị ăn mòn.'),2:('K01','Không xét sự chênh lệch thế điện cực.'),3:('D01','Bỏ qua điều kiện không khí ẩm.')})
mc(12,5,'Thông hiểu','Đại cương về kim loại','Trong các hydroxide sau, chất có tính lưỡng tính là',['NaOH','KOH','Ba(OH)₂','Al(OH)₃'],3,'Al(OH)₃ có thể phản ứng với acid và với base mạnh; NaOH, KOH và Ba(OH)₂ chủ yếu là base.',{0:('K01','Nhầm base mạnh với chất lưỡng tính.'),1:('K01','Nhầm khả năng phân li với tính lưỡng tính.'),2:('K01','Nhầm hydroxide kiềm thổ với hydroxide lưỡng tính.')})
mc(12,7,'Thông hiểu','Phức chất','Trong ion phức [Cu(NH₃)₄]²⁺, số phối trí của Cu là',['2','6','1','4'],3,'Có 4 phối tử NH₃ đơn càng liên kết với tâm Cu, nên số phối trí là 4.',{0:('K01','Lấy điện tích ion phức làm số phối trí.'),1:('K01','Nhầm số liên kết/độ hóa trị.'),2:('D02','Không đọc chỉ số 4 của NH₃.')})
# TF (2/grade)
tf(10,3,'Oxi hóa – khử','Xét phản ứng Zn + CuSO₄ → ZnSO₄ + Cu.', ['Zn bị oxi hóa.','Cu²⁺ nhận electron.','Zn là chất oxi hóa.','Số oxi hóa của Cu giảm từ +2 xuống 0.'],[True,True,False,True],['Zn⁰ → Zn²⁺ + 2e.','Cu²⁺ + 2e → Cu⁰.','Zn nhường electron nên là chất khử.','Cu²⁺ có số oxi hóa +2 và Cu đơn chất có số oxi hóa 0.'])
tf(10,6,'Halogen','Xét một số nhận định về halogen.', ['Ở điều kiện thường, Cl₂ là chất khí màu vàng lục.','Br₂ có tính oxi hóa mạnh hơn Cl₂.','Cl₂ oxi hóa được ion Br⁻ trong dung dịch.','Dung dịch NaCl có thể điều chế Br₂ từ NaBr bằng phản ứng thế halogen.'],[True,False,True,False],['Cl₂ là khí vàng lục.','Cl₂ có tính oxi hóa mạnh hơn Br₂.','Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂.','Ion Cl⁻ không oxi hóa được Br⁻ để tạo Br₂.'])
tf(11,0,'Cân bằng hóa học','Xét cân bằng N₂O₄(g) ⇌ 2NO₂(g), ΔᵣH° > 0 theo chiều thuận.', ['Phản ứng thuận thu nhiệt.','Tăng nhiệt độ làm cân bằng chuyển dịch theo chiều tạo NO₂.','Tăng áp suất (giữ nhiệt độ) làm cân bằng chuyển theo chiều tạo NO₂.','Ở cân bằng, phản ứng thuận và nghịch vẫn xảy ra.'],[True,True,False,True],['ΔH thuận > 0: thu nhiệt.','Tăng nhiệt độ ưu tiên chiều thu nhiệt.','Tăng áp suất ưu tiên phía ít mol khí, tức N₂O₄.','Cân bằng hóa học là cân bằng động.'])
tf(11,1,'Nitric acid','Xét tính chất hóa học của nitric acid.', ['HNO₃ là acid mạnh.','HNO₃ đặc có tính oxi hóa mạnh.','Cu tác dụng với HNO₃ loãng luôn giải phóng khí H₂.','Trong phản ứng 3Cu + 8HNO₃(loãng) → 3Cu(NO₃)₂ + 2NO + 4H₂O, Cu là chất khử.'],[True,True,False,True],['HNO₃ phân li mạnh trong dung dịch nước loãng.','N(+5) trong HNO₃ có thể bị khử.','Sản phẩm khử N của HNO₃ không phải H₂; bài mẫu cho NO.','Cu nhường electron, bị oxi hóa từ 0 lên +2.'])
tf(12,0,'Ester','Xét ethyl acetate (CH₃COOC₂H₅).', ['Ethyl acetate là ester.','Ethyl acetate thủy phân trong môi trường kiềm cho sodium acetate.','Một mol ethyl acetate phản ứng với 2 mol NaOH theo phương trình xà phòng hóa.','Sản phẩm alcohol khi thủy phân kiềm ethyl acetate là ethanol.'],[True,True,False,True],['Chất chứa nhóm –COO– của ester.','Tạo CH₃COONa.','Ester đơn chức với NaOH có tỉ lệ 1:1.','Nhóm –OC₂H₅ tạo C₂H₅OH.'])
tf(12,4,'Điện hóa học','Xét pin Zn–Cu có cầu muối.', ['Zn là anode nơi xảy ra oxi hóa.','Electron đi từ Zn sang Cu trong mạch ngoài.','Ion trong cầu muối giúp duy trì cân bằng điện tích.','Cực Cu là anode trong pin Zn–Cu hoạt động tự phát.'],[True,True,True,False],['Zn → Zn²⁺ + 2e.','Electron di chuyển Zn → Cu.','Cầu muối khép kín mạch ion.','Cu đóng vai trò cathode xảy ra khử.'])
# numeric short 2/grade
short(10,0,'Lượng chất','Tính số mol của 5,6 g Fe; lấy M(Fe) = 56 g/mol. (Chỉ nhập số mol.)',0.1,'n(Fe)=m/M=5,6/56=0,1 mol.',code='T01')
short(10,3,'Tính theo PTHH','Phản ứng: 2Mg + O₂ → 2MgO. Cho 0,4 mol Mg phản ứng hoàn toàn với O₂ dư. Tính số mol MgO tạo thành. (Chỉ nhập số.)',0.4,'Theo tỉ lệ mol Mg : MgO = 1 : 1 nên n(MgO)=0,4 mol.',code='T01')
short(11,1,'Tính theo PTHH','Theo phương trình 3Cu + 8HNO₃(loãng) → 3Cu(NO₃)₂ + 2NO + 4H₂O, nếu 0,30 mol Cu phản ứng hoàn toàn, NO là sản phẩm khử duy nhất, tính số mol NO. (Chỉ nhập số.)',0.2,'n(NO)=0,30×2/3=0,20 mol.',code='T01')
short(11,0,'pH','Ở 25 °C, dung dịch HCl có [H⁺]=0,001 mol/L. Tính pH. (Chỉ nhập số.)',3,'pH=−log₁₀(10⁻³)=3.',code='T04')
short(12,0,'Xà phòng hóa','Cho 0,25 mol CH₃COOC₂H₅ phản ứng vừa đủ với NaOH. Tính số mol NaOH cần. (Chỉ nhập số.)',0.25,'n(NaOH)=n(ester)=0,25 mol.',code='T01')
short(12,4,'Định luật Faraday','Điện phân dung dịch CuSO₄ với điện cực trơ, giả sử hiệu suất 100%. Dòng điện truyền 0,20 mol electron. Tính số mol Cu bám ở cathode. (Chỉ nhập số.)',0.1,'Cu²⁺ + 2e → Cu, nên n(Cu)=0,20/2=0,10 mol.',code='T01')
# essay 1 / grade
essay(10,3,'Cân bằng oxi hóa – khử','Cân bằng phản ứng Fe²⁺ + MnO₄⁻ + H⁺ → Fe³⁺ + Mn²⁺ + H₂O trong môi trường acid bằng phương pháp electron. Giải thích chất oxi hóa, chất khử.',['Viết hai quá trình nhường/nhận electron','Lấy hệ số electron phù hợp','Hoàn tất phương trình ion: 5Fe²⁺ + MnO₄⁻ + 8H⁺ → 5Fe³⁺ + Mn²⁺ + 4H₂O','Xác định MnO₄⁻ là chất oxi hóa; Fe²⁺ là chất khử'])
essay(11,1,'Nitric acid','Viết phương trình phản ứng của Cu với HNO₃ loãng (giả thiết khí NO là sản phẩm khử duy nhất). Phân tích vì sao phương trình Cu + 2HNO₃ → Cu(NO₃)₂ + H₂ không phù hợp.',['Phương trình: 3Cu + 8HNO₃ → 3Cu(NO₃)₂ + 2NO + 4H₂O','Nhận diện HNO₃ có tính oxi hóa; Cu nhường electron, N(+5) nhận electron','Nêu sai lầm áp dụng acid thường tạo H₂ với kim loại','Kiểm tra bảo toàn nguyên tố và electron'])
essay(12,0,'Ester','Trình bày phương trình thủy phân ethyl acetate trong môi trường acid và kiềm. Nêu sự khác nhau về sản phẩm và tính thuận nghịch.',['Acid: CH₃COOC₂H₅ + H₂O ⇌ CH₃COOH + C₂H₅OH (H⁺, t°)','Kiềm: CH₃COOC₂H₅ + NaOH → CH₃COONa + C₂H₅OH','Giải thích tạo muối carboxylate làm phản ứng kiềm đi theo chiều tạo sản phẩm trong điều kiện thông thường','Viết điều kiện, kí hiệu và bảo toàn đúng'])
